#define main sequence_writing_main
#include "sequences.c"
#undef main
int main(int argc,char**argv){if(argc<2)return 2;setvbuf(stdout,NULL,_IONBF,0);FILE*f=fopen(argv[1],"rb");if(!f)return 2;fseek(f,0,SEEK_END);long len=ftell(f);rewind(f);uint8_t*data=malloc(len?len:1);if(fread(data,1,len,f)!=(size_t)len)return 2;fclose(f);heif_context*c=heif_context_alloc();heif_error e=heif_context_read_from_memory(c,data,len,NULL);error(e);context(c);free(data);int n=heif_context_number_of_sequence_tracks(c);uint32_t ids[20]={0};if(n>20)return 2;heif_context_get_track_ids(c,ids);for(int i=0;i<n;i++){heif_track*t=heif_context_get_track(c,ids[i]);query(t);for(int j=0;j<5;j++){if(heif_track_get_track_handler_type(t)==heif_track_type_metadata){heif_raw_sequence_sample*s=(void*)(uintptr_t)1;e=heif_track_get_next_raw_sequence_sample(t,&s);error(e);printf(" out%d",s==(void*)(uintptr_t)1?1:s?2:0);if(!e.code&&s){printf(" sample%u,%zu:",heif_raw_sequence_sample_get_duration(s),heif_raw_sequence_sample_get_data_size(s));size_t z=0;const uint8_t*p=heif_raw_sequence_sample_get_data(s,&z);for(size_t k=0;k<z;k++)printf("%02x",p[k]);string(heif_raw_sequence_sample_get_gimi_sample_content_id(s));heif_raw_sequence_sample_release(s);}}else{heif_image*img=(void*)(uintptr_t)1;e=heif_track_decode_next_image(t,&img,heif_colorspace_undefined,heif_chroma_undefined,NULL);error(e);printf(" out%d",img==(void*)(uintptr_t)1?1:img?2:0);if(!e.code&&img){pixels(img);heif_image_release(img);}}}heif_track_release(t);}heif_context_free(c);puts("");return 0;}
